/** Every MK-NW-F record in the code, read from the code: the header rule printed directly above each function (the one the card
 *  builder and guard_function_descriptions read), with the file that declares it (2026-10-26, PF-TOOLS — the CF table's fix of
 *  2026-10-24, carried to this one). */
function headersInCode(): Map<string, string> {
  const out = new Map<string, string>();
  const walk = (dir: string) => {
    for (const f of fs.readdirSync(dir, { withFileTypes: true })) {
      if (f.name === 'node_modules') continue;
      const p = path.join(dir, f.name);
      if (f.isDirectory()) { walk(p); continue; }
      if (!/\.tsx?$/.test(f.name) || /\.test\./.test(f.name)) continue;
      for (const m of fs.readFileSync(p, 'utf8').matchAll(/\/\* ─ (MK-NW-F-\d{3}) ─/g)) if (!out.has(m[1])) out.set(m[1], path.relative(ROOT, p));
    }
  };
  for (const c of ['src', 'MoneyKeel/functions', 'Calculation Module code/engines']) walk(path.join(ROOT, c));
  return out;
}

describe('every Net worth function traces to its proof in one hop (step 3.c)', () => {
  it('the table covers every Net worth function in the code — and says how many', () => {
    // 100, not 101 (2026-10-01): the 101st was a retired MK-NW-F-074 header left above theEmergencyFund's
    // real one (MK-NW-O-004) — one function counted twice, not a function lost.
    // 98, not 100 (2026-10-14): four saved-account functions (MK-NW-F-042, -043, -044, -111) were retired — nothing in the
    // app called them (inputs-and-use audit). The floor carries the true number.
    // 91, not 98 (2026-10-19): seven more were removed by his approval DEC-5758 ("Removing #4,5,6,7-10,11 - approved.") —
    // MK-NW-F-013, -015, -017, -018, -019, -020, -038; nothing in the app called them. The floor carries the true number.
    // 90, not 91 (2026-10-19, same day): the eighth, MK-NW-F-006 isCashKind, followed once the Net worth screen's unused
    // import of it was taken out. The floor carries the true number.
    expect(FUNCTIONS.length).toBeGreaterThanOrEqual(172);   // 172 on 2026-11-02 (PF-TOOLS round 6: MK-NW-F-187 heldBondInterest); 171 on 2026-10-30 (PF-TOOLS: MK-NW-F-186, FX-NW's accruedFrequencyAssumed); 170 on 2026-10-26: 80 rows were missing (MK-NW-F-103 to 185) — the typed floor of 90 passed them
    expect(new Set(FUNCTIONS.map((r) => r[0])).size).toBe(FUNCTIONS.length);
    // THE GUARD PROVES IT LOOKED (2026-10-26, PF-TOOLS): it read a typed floor and nothing else, so every function numbered after the
    // table was printed passed unseen — the CF table's fault of 2026-10-24. The table must be exactly the code's MK-NW-F records.
    const code = headersInCode();
    console.log(`nw_function_trace: ${code.size} MK-NW-F records in the code, ${FUNCTIONS.length} rows in the table`);
    expect(code.size).toBeGreaterThanOrEqual(172);
    const table = new Set(FUNCTIONS.map((r) => r[0]));
    expect([...code.keys()].filter((id) => !table.has(id)).sort()).toEqual([]);   // in the code, missing from the table
    expect([...table].filter((id) => !code.has(id)).sort()).toEqual([]);          // in the table, gone from the code
    expect(FUNCTIONS.filter(([id, src]) => code.get(id) !== src).map(([id, src]) => `${id}: the table says ${src}, the code declares it in ${code.get(id)}`)).toEqual([]);
  });

  it('each identifier really is in the file this table names', () => {
    const wrong: string[] = [];
    for (const [id, src] of FUNCTIONS) {
      const p = path.join(ROOT, src);
      if (!fs.existsSync(p) || !fs.readFileSync(p, 'utf8').includes(id)) wrong.push(`${id} → ${src}`);
    }
    expect(wrong).toEqual([]);
  });

  it('the eight functions he removed on 2026-10-19 (DEC-5758) are gone from the code and retired in the register', () => {
    const gone: [string, string][] = [['MK-NW-F-006', 'isCashKind'], ['MK-NW-F-013', 'realEstateUseOf'], ['MK-NW-F-015', 'totalAssets'],
      ['MK-NW-F-017', 'equitiesTotal'], ['MK-NW-F-018', 'fixedIncomeTotal'], ['MK-NW-F-019', 'alternativesTotal'],
      ['MK-NW-F-020', 'realEstateTotal'], ['MK-NW-F-038', 'earmarkedKinds']];
    const assets = fs.readFileSync(path.join(ROOT, 'src/domain/assets/index.ts'), 'utf8');
    const register = JSON.parse(fs.readFileSync(path.join(ROOT, 'Calculation Module code/scripts/moneykeel_function_register.json'), 'utf8'));
    const left = gone.filter(([id, name]) => new RegExp(`export (function|const) ${name}\\b`).test(assets)
      || register.issued[name] || !String(register.retired[id] ?? '').includes('DEC-5758'));
    expect(left).toEqual([]);
    expect(gone.length).toBe(8);
    // and the Net worth screen's import from the accounts code names none of them (it named MK-NW-F-006 in an unused
    // import; its own local "totalAssets" figure is a variable, not the removed function, so only the import is read)
    const screen = fs.readFileSync(path.join(ROOT, 'src/screens/NetWorthScreen.tsx'), 'utf8');
    const imported = (screen.match(/import \{([^}]*)\} from '\.\.\/domain\/assets'/) ?? [])[1];
    expect(imported).toBeDefined();
    expect(gone.filter(([, name]) => new RegExp(`\\b${name}\\b`).test(imported!))).toEqual([]);
  });

  it('each function names a test that exists', () => {
    const missing = FUNCTIONS.filter(([, , t]) => !t || !fs.existsSync(path.join(ROOT, t)))
      .map(([id, src]) => `${id} in ${src} — no test exercises this file`);
    expect(missing).toEqual([]);
  });
});
